package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.view.KeyEvent;import org.json.*;import java.io.*;
/** Production WebView/SQLite and real touch/keyboard; isolated synthetic chat and controlled model replies. */
public final class ChatScrollTest extends DocumentEditorTest {
 JSONArray results=new JSONArray();
 JSONObject position(String stage)throws Exception{JSONObject o=new JSONObject(h.js("(()=>{const b=document.querySelector('#chat-scroll'),ms=[...document.querySelectorAll('.chat-message')];return {stage:"+JSONObject.quote(stage)+",top:b.scrollTop,height:b.clientHeight,scrollHeight:b.scrollHeight,gap:b.scrollHeight-b.clientHeight-b.scrollTop,keyboard:document.body.classList.contains('chat-keyboard'),count:ms.length,order:ms.map(m=>m.dataset.messageId)}})()"));results.put(o);return o;}
 void atEnd(String stage)throws Exception{JSONObject p=position(stage);check(Math.abs(p.getDouble("gap"))<3,stage+": visible chat stays at latest end (gap="+p.getDouble("gap")+")");}
 void prepare(int count,boolean longReply)throws Exception{
  h.call("newChat",new JSONObject());for(int i=0;i<count;i++)h.call("saveMessage",new JSONObject().put("message",new JSONObject().put("id","chat-scroll-"+System.nanoTime()).put("role",i%2==0?"user":"assistant").put("text","合成历史第"+i+"条。\n\n这是用于测试滚动的内容，不包含私人数据。\n\n新一轮消息必须接在上一轮之后。").put("createdAt",1700000000000L+i)));
  h.js("window.__reloadChat=true;location.reload()");until("window.__reloadChat===undefined&&document.body.innerText.includes('今天的投入')");
  String answer=longReply?new String(new char[45]).replace("\0","这是合成长回复的段落，只测试滚动位置，不代表真实用户数据。\n\n"):"合成回答：新一轮对话已接在最新回答后面。";
  h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{};window.__chatNative=LifeNative;window.__answer="+JSONObject.quote(answer)+";window.__pendingReply=null;window.__error=false;LifeNative={call:(a,p,id)=>{if(a!=='ask'){__chatNative.call(a,p,id);return;}const req=JSON.parse(p);if(req.tool?.name==='plan_record_search'){setTimeout(()=>nativeReply({id,data:{text:JSON.stringify({intent:'general',topic:'',keywords:[],dateStart:'',dateEnd:'',recordTypes:[]}),model:'synthetic-scroll-test'}}),20);return;}__pendingReply=()=>{nativeReply(__error?{id,error:'合成网络中断'}:{id,data:{text:JSON.stringify({answer:__answer,records:[],citations:[],actions:[]}),model:'synthetic-scroll-test'}});__pendingReply=null;};}};document.querySelector('[data-page=chat]').click()");Thread.sleep(300);
 }
 void send(String text)throws Exception{h.js("document.querySelector('#chat-input').value="+JSONObject.quote(text)+";document.querySelector('#chat-input').dispatchEvent(new Event('input'))");h.tap("[data-action=send]",false);until("!!__pendingReply");Thread.sleep(120);}
 void reply(int count)throws Exception{h.js("__pendingReply()");until("!document.querySelector('.loading')&&document.querySelectorAll('.chat-message').length==="+count);Thread.sleep(150);}
 void scenario(String name,int count,boolean longReply,boolean old,boolean keyboard,boolean attachment)throws Exception{
  prepare(count,longReply);if(keyboard){int height=Integer.parseInt(h.js("innerHeight"));h.tap("#chat-input",false);until("innerHeight<"+(height-100));until("document.body.classList.contains('chat-keyboard')");}if(old){h.js("document.querySelector('#chat-scroll').scrollTop=0");Thread.sleep(150);}if(attachment){h.js("nativeEvent('attachment',{kind:'text',name:'合成附件.txt',text:'仅用于测试滚动的合成附件。'})");until("!!document.querySelector('.attachment')");}
  position(name+"/before");send("这是一条合成指令：请直接回答测试确认，不要保存任何记录。");atEnd(name+"/sending");if(name.equals("history_short"))h.screenshot("chat-scroll-fixed-sending.png");reply(count+2);atEnd(name+"/reply");
  check(h.js("(()=>{const ms=[...document.querySelectorAll('.chat-message')],a=ms[ms.length-2],b=ms[ms.length-1];return a.classList.contains('user')&&!b.classList.contains('user')&&a.querySelector('.message-content').textContent.includes('合成指令')})()").equals("true"),name+": new messages append in chronological order");
  if(name.equals("history_short"))h.screenshot("chat-scroll-fixed-reply.png");if(keyboard){h.screenshot("chat-scroll-fixed-keyboard.png");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(500);atEnd(name+"/keyboard_closed");}
 }
 @Override public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;String previous=getTargetContext().getSharedPreferences("secure",0).getString("settings",null);try{
  h=new MainHost(this);h.open();model();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.13.1"),"Signed 1.13.1 installed");
  scenario("empty",0,false,false,false,false);scenario("history_short",20,false,false,false,false);scenario("history_long",20,true,false,false,false);scenario("reading_old",20,false,true,false,false);scenario("keyboard_short",20,false,false,true,false);scenario("keyboard_long",20,true,false,true,false);scenario("attachment",20,false,false,false,true);
  prepare(20,true);send("这是一条合成指令：请直接回答测试确认，不要保存任何记录。");atEnd("manual_history/sending");h.js("document.querySelector('#chat-scroll').scrollTop=450");Thread.sleep(150);double before=position("manual_history/reading").getDouble("top");reply(22);JSONObject after=position("manual_history/reply");check(Math.abs(after.getDouble("top")-before)<3&&after.getDouble("gap")>100,"Reading history during request is not interrupted by new reply");check(h.js("!document.querySelector('#chat-bottom').hidden").equals("true"),"Latest-message button remains available while reading history");h.screenshot("chat-scroll-fixed-reading-history.png");h.js("document.querySelector('#chat-input').value='未发送草稿';document.querySelector('#chat-input').dispatchEvent(new Event('input'))");h.tap("#chat-bottom",false);Thread.sleep(900);atEnd("manual_history/latest_button");check(h.js("document.querySelector('#chat-input').value==='未发送草稿'").equals("true"),"Jumping to latest preserves draft");
  prepare(20,false);h.js("__error=true");send("这是一条合成指令：请直接回答测试确认，不要保存任何记录。");reply(22);atEnd("network_error/reply");check(h.js("[...document.querySelectorAll('.chat-message')].at(-1).textContent.includes('合成网络中断')").equals("true"),"Network failure message is also visible at latest end");
  out.putString("stream","PASS ChatScrollTest: "+passed+" checks; synthetic model replies, production WebView\n");code=Activity.RESULT_OK;
 }catch(Throwable e){try{h.screenshot("chat-scroll-failure.png");}catch(Exception ignored){}out.putString("stream","FAIL ChatScrollTest after "+passed+": "+e+"\n");}finally{File dir=new File(getTargetContext().getFilesDir(),"qa");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,"chat-scroll-fixed.json"))){f.write(results.toString(2).getBytes("UTF-8"));}catch(Exception ignored){}android.content.SharedPreferences.Editor ed=getTargetContext().getSharedPreferences("secure",0).edit();if(previous==null)ed.remove("settings");else ed.putString("settings",previous);ed.commit();}finish(code,out);}
}
